namespace RonSijm.FluidHumidifier.Factories.Kinesis;

public class ChannelFactory(string resourceName = null, Action<Humidifier.Kinesis.Channel> factoryAction = null) : ResourceFactory<Humidifier.Kinesis.Channel>(resourceName)
{

    internal List<InnerChannelStreamConfigurationFactory> StreamConfigurationListFactories { get; set; } = [];

    internal InnerChannelEncryptionConfigurationFactory EncryptionConfigurationFactory { get; set; }

    internal InnerChannelS3DestinationConfigurationFactory S3DestinationConfigurationFactory { get; set; }

    internal InnerChannelLoggingConfigurationFactory LoggingConfigurationFactory { get; set; }

    internal InnerChannelS3TablesDestinationConfigurationFactory S3TablesDestinationConfigurationFactory { get; set; }

    protected override Humidifier.Kinesis.Channel Create()
    {
        var channelResult = CreateChannel();
        factoryAction?.Invoke(channelResult);

        return channelResult;
    }

    private Humidifier.Kinesis.Channel CreateChannel()
    {
        var channelResult = new Humidifier.Kinesis.Channel
        {
            GivenName = InputResourceName,
        };

        return channelResult;
    }
    public override void CreateChildren(Humidifier.Kinesis.Channel result)
    {
        base.CreateChildren(result);

        result.StreamConfigurationList = StreamConfigurationListFactories.Any() ? StreamConfigurationListFactories.Select(x => x.Build()).ToList() : null;
        result.EncryptionConfiguration ??= EncryptionConfigurationFactory?.Build();
        result.S3DestinationConfiguration ??= S3DestinationConfigurationFactory?.Build();
        result.LoggingConfiguration ??= LoggingConfigurationFactory?.Build();
        result.S3TablesDestinationConfiguration ??= S3TablesDestinationConfigurationFactory?.Build();
    }

} // End Of Class

